import sys
import math
from heapq import heappop, heappush

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    nodes = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n)]

    def distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def find_mst_with_constraints():
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                if nodes[i][1] > nodes[j][1]:
                    heappush(edges, (distance(nodes[i], nodes[j]), i, j))
                elif nodes[j][1] > nodes[i][1]:
                    heappush(edges, (distance(nodes[j], nodes[i]), j, i))

        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                if rank[rootX] > rank[rootY]:
                    parent[rootY] = rootX
                elif rank[rootX] < rank[rootY]:
                    parent[rootX] = rootY
                else:
                    parent[rootY] = rootX
                    rank[rootX] += 1
                return True
            return False

        mst_weight = 0
        edge_count = 0
        while edges:
            weight, u, v = heappop(edges)
            if union(u, v):
                mst_weight += weight
                edge_count += 1
                if edge_count == n - 1:
                    return mst_weight
        return -1

    result = find_mst_with_constraints()
    if result == -1:
        print("-1")
    else:
        print(f"{result:.10f}")

main()
